mapper.select:
SELECT CD.*
FROM shopion.tPrfCustCpnDetail CD
INNER JOIN shopion.tStrCustCpn C ON CD.CpnId = C.CpnId
WHERE CD.CustId = #{custId}
AND CD.CpnNo = #{cpnNo}

mapper.insert:
INSERT INTO shopion.tPrfCustCpnDetail (
    CustId, CpnId, UseYn, UseDate, State, Remark, RegistDate, RegistId, RegistName
) VALUES (
    #{custId}, #{cpnId}, #{useYn}, #{useDate}, #{state}, #{remark}, NOW(), #{registId}, #{registName}
)

mapper.update:
UPDATE shopion.tPrfCustCpnDetail SET
    CpnId = #{cpnId}, UseYn = #{useYn}, UseDate = #{useDate},
    State = #{state}, Remark = #{remark},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE CustId = #{custId}
AND CpnNo = #{cpnNo}

UPDATE shopion.tPrfCustCpnDetail SET
    UseYn = #{useYn}, UseDate = #{useDate},
    State = #{state}, Remark = #{remark},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE CustId = #{custId}

mapper.delete:
DELETE FROM shopion.tPrfCustCpnDetail
WHERE CustId = #{custId}
AND CpnNo = #{cpnNo}

mapper.update:
UPDATE shopion.tPrfCustCpnDetail SET UseYn = 1, UseDate = NOW()
WHERE CustId = #{custId}
AND CpnNo = #{cpnNo}

UPDATE shopion.tPrfCustCpnDetail SET UseYn = 0, UseDate = NULL
WHERE CustId = #{custId}
AND CpnNo = #{cpnNo}
